# link-preview service (Flask), runs on the EC2 instance
import requests
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/preview")
def preview():
    url = request.args.get("url", "")
    # fetch the page the user pasted and return its status and first 500 bytes
    resp = requests.get(url, timeout=3, allow_redirects=True)
    return jsonify({"status": resp.status_code, "snippet": resp.text[:500]})

